import{_ as e,o as i,a as l,b as a}from"./app.C41L12d5.js";const t="/ascendc.github.io/assets/bufpool_resource_pool.BGm0LFl5.png",_=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"资源管理","link":"/api/SIMD-API/basic_api/resource_management/resource_management"},{"text":"TBufPool","link":"/api/SIMD-API/basic_api/resource_management/TBufPool/TBufPool"},{"text":"TBufPool简介","link":"/api/SIMD-API/basic_api/resource_management/TBufPool/TBufPool_intro"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/resource_management/TBufPool/TBufPool_intro.md","filePath":"api/SIMD-API/basic_api/resource_management/TBufPool/TBufPool_intro.md","outlineHeaders":[{"level":2,"title":"功能图示","slug":"功能图示","link":"#功能图示"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"}],"lastUpdated":1787050286000}'),f={name:"api/SIMD-API/basic_api/resource_management/TBufPool/TBufPool_intro.md"};function n(u,o,r,P,s,B){return i(),l("div",null,[...o[0]||(o[0]=[a('<div><article class="markdown-body"><h1>TBufPool简介<span id="ZH-CN_TOPIC_0000001912912993"></span></h1><p>TPipe可以管理全局内存资源，而TBufPool可以手动管理或复用Unified Buffer（UB）/L1 Buffer物理内存，主要用于多个stage计算中UB/L1 Buffer物理内存不足的场景。</p><h2 id="功能图示">功能图示<span id="section10900194131112"></span><a class="header-anchor" href="#功能图示">​</a></h2><p>下图展示了资源池划分的过程：</p><ol><li>通过TPipe::<a href="../TPipe/InitBuffer.html">InitBuffer</a>接口可以申请Buffer内存并使用队列进行管理；</li><li>通过TPipe::<a href="../TPipe/InitBufPool.html">InitBufPool</a>可以划分出资源池BufPool1；</li><li>通过TPipe::<a href="../TPipe/InitBufPool.html">InitBufPool</a>可以指定BufPool1与BufPool3地址和长度复用;</li><li>通过TBufPool::<a href="InitBuffer.html">InitBuffer</a>及TBufPool::<a href="InitBufPool.html">InitBufPool</a>接口继续将BufPool1及BufPool3划分成Buffer或TBufPool资源池。</li></ol><p><strong>图1</strong> BufPool资源池划分<span id="fig14900125316552"></span><br><img src="'+t+'" alt title="BufPool资源池划分"></p><p>如图示的嵌套关系，最外层TBufPool(BufPool1与BufPool3)需要通过TPipe::InitBufPool申请并初始化，内层TBufPool(BufPool2)可以通过TBufPool::InitBufPool申请并初始化。</p><h2 id="约束说明">约束说明<span id="section8236029104012"></span><a class="header-anchor" href="#约束说明">​</a></h2><ol><li>TBufPool必须通过TPipe::InitBufPool或TBufPool::InitBufPool接口进行划分和初始化；资源池只能整体划分成部分，无法部分拼接为整体；</li><li>不同TBufPool资源池切换进行计算时，需要调用TBufPool::Reset()接口清空已完成计算的TBufPool，清空后的TBufPool资源池及分配的Buffer和数据默认无效；</li><li>不同资源池间分配的Buffer无法混用避免数据踩踏；</li><li>AllocTensor/FreeTensor、EnQue/DeQue在切分TBufPool资源池时必须成对匹配使用，自动确保同步；</li><li>切换资源池的时候，若手写同步，Ascend C不保证地址读写复用同步，因此不推荐手写同步。</li></ol></article></div>',1)])])}const T=e(f,[["render",n]]);export{_ as __pageData,T as default};
